///////// 2. 초기화 영역 /////////

// [A] 초기 목록 미해결 — jldods60401_pop: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldods60401_pop.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.grd_reportList_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_reportList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_reportList');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_reportList'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (typeof scwin.fnWrite === 'function') { scwin.fnWrite(r["formCd"]); } else { console.error('[sdd] 행 동작 미정의: scwin.fnWrite (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.fnWrite'); } return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_reportList.oncellclick' });
    }
};


///////// 4. 서브미션 콜백 영역 /////////



